import 'https://testingcf.jsdelivr.net/gh/MagicalAstrogy/MagVarUpdate/artifact/bundle.js'

/* ============================================================
 * KK园区 MVU 变量管理脚本
 * 功能：MVU变量读写、LCG确定性骰子、状态栏刷新、事件监听
 * 环境：SillyTavern TavernHelper
 * 说明：不使用SPV数据库(chatSheets)，仅MVU单源
 * ============================================================ */

/* ========= TavernHelper 扩展上下文 ========= */
var extensionCtx = null;
try {
  if (typeof tavernHelper !== 'undefined' && tavernHelper && tavernHelper.extensionCtx) {
    extensionCtx = tavernHelper.extensionCtx;
  }
} catch (e) {}

/* ========= 工具函数 ========= */
function hasMeaningfulStatData(stat) {
  return stat && typeof stat === 'object' && !Array.isArray(stat) && Object.keys(stat).length > 0;
}

function pickStatData(source) {
  if (!source || typeof source !== 'object') return null;
  var stat = source.stat_data;
  return hasMeaningfulStatData(stat) ? stat : null;
}

function cloneObj(obj) {
  if (!obj || typeof obj !== 'object') return {};
  try { return JSON.parse(JSON.stringify(obj)); } catch (e) { return {}; }
}

/* ========= DEFAULT_STAT 兜底常量（与 initvar.yaml 一致） ========= */
var DEFAULT_STAT = {
  "身份系统": {
