// ────────────────────────────────────────────────────────────
// 一、强制校验开关（不可被AI关闭）
// ────────────────────────────────────────────────────────────
const ANTI_CHEAT_CONFIG = {
  enabled: true,                    // 总开关（强制true）
  strict_mode: true,                // 严格模式（强制true）
