// ────────────────────────────────────────────────────────────
// 四、身份阶段校验矩阵（每种身份的合法叙事阶段序列）
// ────────────────────────────────────────────────────────────
const IDENTITY_STAGE_MATRIX = {
  '受害者': ['入园恐惧', '适应期', '收集情报', '逃跑准备', '结局'],
  '管理者': ['上任', '业绩压力', '内心动摇', '抉择', '结局'],
  '打手': ['执行任务', '动摇', '挣扎', '抉择', '结局'],
  '老板': ['统治', '外部压力', '内部危机', '覆灭', '结局']
};

// ────────────────────────────────────────────────────────────
// 五、强制校验函数
// ────────────────────────────────────────────────────────────
function validateAction(action_type, context) {
  const _result = {
    valid: true,
    violations: [],
    warnings: [],
    blocked: false,
    action_type: action_type
  };

  const _req = ACTION_FLAG_REQUIREMENTS[action_type];
  if (!_req) return _result;

  // 校验身份（单选）
  if (_req.required_identity) {
    const _cur_identity = String(getvar('stat_data.身份系统.当前身份', { scope: 'local', defaults: '' }) || '');
    if (_cur_identity !== _req.required_identity) {
      _result.valid = false;
      _result.violations.push({
        rule: 'identity_mismatch',
        actual: _cur_identity,
        required: _req.required_identity,
        desc: `${action_type}需要身份${_req.required_identity}，当前${_cur_identity}`
      });
    }
  }

  // 校验身份（多选，如拍卖上架允许老板/管理者）
  if (_req.required_身份 && Array.isArray(_req.required_身份)) {
    const _cur_identity = String(getvar('stat_data.身份系统.当前身份', { scope: 'local', defaults: '' }) || '');
    if (_req.required_身份.indexOf(_cur_identity) === -1) {
      _result.valid = false;
      _result.violations.push({
        rule: 'identity_not_allowed',
        actual: _cur_identity,
        required: _req.required_身份.join('/'),
        desc: `${action_type}仅允许${_req.required_身份.join('/')}，当前${_cur_identity}`
      });
    }
  }

  // 校验逃跑准备
  if (_req.required_逃跑准备 !== undefined) {
    const _val = Number(getvar('stat_data.身份.受害者.逃跑准备', { scope: 'local', defaults: 0 })) || 0;
    if (_val < _req.required_逃跑准备) {
      _result.valid = false;
      _result.violations.push({
        rule: 'escape_prep_too_low',
        actual: _val,
        required: _req.required_逃跑准备,
        desc: `逃跑准备不足：需要${_req.required_逃跑准备}，当前${_val}`
      });
    }
  }

  // 校验伪装度
  if (_req.required_伪装度 !== undefined) {
    const _val = Number(getvar('stat_data.身份.受害者.伪装度', { scope: 'local', defaults: 0 })) || 0;
    if (_val < _req.required_伪装度) {
      _result.valid = false;
      _result.violations.push({
        rule: 'disguise_too_low',
        actual: _val,
        required: _req.required_伪装度,
        desc: `伪装度不足：需要${_req.required_伪装度}，当前${_val}`
      });
    }
  }

  // 校验希望值
  if (_req.required_希望值 !== undefined) {
    const _val = Number(getvar('stat_data.身份.受害者.希望值', { scope: 'local', defaults: 80 })) || 80;
    if (_val < _req.required_希望值) {
      _result.valid = false;
      _result.violations.push({
        rule: 'hope_too_low',
        actual: _val,
        required: _req.required_希望值,
        desc: `希望值不足：需要${_req.required_希望值}，当前${_val}`
      });
    }
  }

  // 校验权力接触（布尔，影响D_反杀上位结局）
  if (_req.required_权力接触 !== undefined) {
    const _val = getvar('stat_data.身份.受害者.权力接触', { scope: 'local', defaults: false });
    if (_val !== _req.required_权力接触) {
      _result.valid = false;
      _result.violations.push({
        rule: 'power_access_missing',
        actual: _val,
        required: _req.required_权力接触,
        desc: `权力接触未满足：需要${_req.required_权力接触}，当前${_val}`
      });
    }
  }

  // 校验外部援助（布尔，影响E_被救结局）
  if (_req.required_外部援助 !== undefined) {
    const _val = getvar('stat_data.身份.受害者.外部援助', { scope: 'local', defaults: false });
    if (_val !== _req.required_外部援助) {
      _result.valid = false;
      _result.violations.push({
        rule: 'external_aid_missing',
        actual: _val,
        required: _req.required_外部援助,
        desc: `外部援助未满足：需要${_req.required_外部援助}，当前${_val}`
      });
    }
  }

  // 校验警方线索（整数，≥3触发E_被救结局）
  if (_req.required_警方线索 !== undefined) {
    const _val = Number(getvar('stat_data.身份.受害者.警方线索', { scope: 'local', defaults: 0 })) || 0;
    if (_val < _req.required_警方线索) {
      _result.valid = false;
      _result.violations.push({
        rule: 'police_clues_too_low',
        actual: _val,
        required: _req.required_警方线索,
        desc: `警方线索不足：需要${_req.required_警方线索}，当前${_val}`
      });
    }
  }

  // 校验处境值（女性专属）
  if (_req.required_处境值 !== undefined) {
    const _val = Number(getvar('stat_data.女性专属.处境值', { scope: 'local', defaults: 0 })) || 0;
    if (_val < _req.required_处境值) {
      _result.valid = false;
      _result.violations.push({
        rule: 'situation_too_low',
        actual: _val,
        required: _req.required_处境值,
        desc: `处境值不足：需要${_req.required_处境值}，当前${_val}`
      });
    }
  }

  // 校验关系值（NPC关系为record，由context传入目标NPC关系值）
  if (_req.required_关系值 !== undefined) {
    const _val = Number(context.relationship_value || 0) || 0;
    if (_val < _req.required_关系值) {
      _result.valid = false;
      _result.violations.push({
        rule: 'relationship_too_low',
        actual: _val,
        required: _req.required_关系值,
        desc: `关系值不足：需要${_req.required_关系值}，当前${_val}`
      });
    }
  }

  // 校验信任值
  if (_req.required_信任值 !== undefined) {
    const _val = Number(getvar('stat_data.身份.受害者.信任值', { scope: 'local', defaults: 0 })) || 0;
    if (_val < _req.required_信任值) {
      _result.valid = false;
      _result.violations.push({
        rule: 'trust_too_low',
        actual: _val,
        required: _req.required_信任值,
        desc: `信任值不足：需要${_req.required_信任值}，当前${_val}`
      });
    }
  }

  // 校验剧情进度
  if (_req.required_剧情进度 !== undefined) {
    const _val = Number(getvar('stat_data.身份系统.剧情进度', { scope: 'local', defaults: 1 })) || 1;
    if (_val < _req.required_剧情进度) {
      _result.valid = false;
      _result.violations.push({
        rule: 'plot_progress_too_low',
        actual: _val,
        required: _req.required_剧情进度,
        desc: `剧情进度不足：需要${_req.required_剧情进度}，当前${_val}`
      });
    }
  }

  // 校验暗网知名度
  if (_req.required_暗网知名度 !== undefined) {
    const _val = Number(getvar('stat_data.暗网.暗网知名度', { scope: 'local', defaults: 0 })) || 0;
    if (_val < _req.required_暗网知名度) {
      _result.valid = false;
      _result.violations.push({
        rule: 'darknet_fame_too_low',
        actual: _val,
        required: _req.required_暗网知名度,
        desc: `暗网知名度不足：需要${_req.required_暗网知名度}，当前${_val}`
      });
    }
  }

  // 校验派系关系（context.faction 指定派系名）
  if (_req.required_派系关系 !== undefined) {
    const _faction = context.faction || '管理层';
    const _faction_map = {
      '董事会': 'stat_data.派系.园区董事会',
      '管理层': 'stat_data.派系.管理层',
      '打手团': 'stat_data.派系.打手团',
      '受害者群': 'stat_data.派系.受害者群',
      '暗网网络': 'stat_data.派系.暗网网络'
    };
    const _path = _faction_map[_faction] || 'stat_data.派系.管理层';
    const _val = Number(getvar(_path, { scope: 'local', defaults: 0 })) || 0;
    if (_val < _req.required_派系关系) {
      _result.valid = false;
      _result.violations.push({
        rule: 'faction_relation_too_low',
        actual: _val,
        required: _req.required_派系关系,
        desc: `${_faction}关系不足：需要${_req.required_派系关系}，当前${_val}`
      });
    }
  }

  // 阻止非法操作
  if (!_result.valid && ANTI_CHEAT_CONFIG.block_invalid_changes) {
    _result.blocked = true;
  }

  return _result;
}

// ────────────────────────────────────────────────────────────
// 六、强制检查清单（6项，AI思维链必须逐条确认）
// ────────────────────────────────────────────────────────────
const MANDATORY_CHECKLIST = [
  '1. 检查当前身份是否匹配操作要求',
  '2. 检查相关变量是否达到阈值（逃跑准备/伪装度/希望值等）',
  '3. 检查是否满足结局触发条件（剧情进度≥80+结局分支匹配）',
  '4. 检查NPC关系值是否足够触发NSFW（关系值≥80+处境值≥40）',
  '5. 检查逃跑/反杀准备是否充分（权力接触/警方线索/外部援助）',
  '6. 检查变量变化是否在合理范围内（希望值±20/金钱10000/关系值30）'
];

// ────────────────────────────────────────────────────────────
// 七、违规记录系统（局部数组，每次EJS执行重新初始化）
// ────────────────────────────────────────────────────────────
var _violations = [];
function logViolation(violation_type, details, severity) {
  _violations.push({
    timestamp: getvar('stat_data.通用.时间.天数', { scope: 'local', defaults: 1 }) + '_' + getvar('stat_data.通用.时间.时段', { scope: 'local', defaults: '清晨' }),
    type: violation_type,
    severity: severity || 'medium',
    details: details
  });
  // 限制记录数量（保留最近20条）
  if (_violations.length > 20) _violations.shift();
}

// ────────────────────────────────────────────────────────────
// 八、注册到全局（供其他EJS条目调用）
// ────────────────────────────────────────────────────────────
define('ANTI_CHEAT_CONFIG', ANTI_CHEAT_CONFIG);
define('ACTION_FLAG_REQUIREMENTS', ACTION_FLAG_REQUIREMENTS);
define('CHEAT_DETECTION_RULES', CHEAT_DETECTION_RULES);
define('IDENTITY_STAGE_MATRIX', IDENTITY_STAGE_MATRIX);
define('validateAction', validateAction);
define('logViolation', logViolation);
define('MANDATORY_CHECKLIST', MANDATORY_CHECKLIST);
-%>

<%_ // 输出防口胡状态摘要 _%>
<%_ const antiCheatStatus = { enabled: ANTI_CHEAT_CONFIG.enabled, rules_count: Object.keys(CHEAT_DETECTION_RULES).length, checklist_count: MANDATORY_CHECKLIST.length }; _%>
<%= JSON.stringify(antiCheatStatus, null, 2) %>
